import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Startup Panel","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/startup-panel.md","filePath":"user-guide/settings/startup-panel.md","lastUpdated":1784692064000}'),o={name:"user-guide/settings/startup-panel.md"};function n(r,e,l,h,d,u){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="startup-panel" tabindex="-1">Startup Panel <a class="header-anchor" href="#startup-panel" aria-label="Permalink to &quot;Startup Panel&quot;">​</a></h1><p>A tab strip shown above the result list in the quick window whenever the search box is empty, giving quick access to recent files, favorites, and history without typing a query.</p><ul><li><strong>Enable the startup panel</strong> — master switch; off means the panel never activates at all, regardless of the per-tab settings below.</li></ul><p>Four sub-tabs: <strong>Recent Files</strong>, <strong>Last Directory</strong>, <strong>Plugin Tabs</strong>, and <strong>Tab Order</strong>.</p><h2 id="recent-files" tabindex="-1">Recent Files <a class="header-anchor" href="#recent-files" aria-label="Permalink to &quot;Recent Files&quot;">​</a></h2><ul><li><strong>Enable panel</strong> — checkbox; shows the tab when the search box is empty.</li><li><strong>Directories</strong> — folders to watch, one per line (same add/edit/remove-row and bulk-text editing as <a href="./index-drives.html#exclusion-rules">Exclusion Rules</a>). Can include local drives, mapped network drives, and WSL paths (<code>\\\\wsl$\\...</code> or <code>\\\\wsl.localhost\\...</code>) — matched against whichever of those you&#39;ve already configured and indexed under <a href="./index-drives.html">Index</a>.</li><li><strong>Maximum number of files to show</strong> — range 1–100, default 10.</li><li><strong>Time range (minutes)</strong> — only files modified within this many minutes of now are eligible, on top of the count cap above. Range 1–43200 (30 days), default 60.</li></ul><p>Each entry&#39;s second line is prefixed with a relative time — &quot;X seconds/minutes/hours/days ago&quot; — built from that file&#39;s last-modified timestamp already stored in the index, so it costs no extra disk access. Hours and days drop the smaller unit when it&#39;s zero (e.g. &quot;2 hours ago&quot; instead of &quot;2 hours 0 minutes ago&quot;).</p><h2 id="last-directory" tabindex="-1">Last Directory <a class="header-anchor" href="#last-directory" aria-label="Permalink to &quot;Last Directory&quot;">​</a></h2><ul><li><strong>Enable panel</strong> — checkbox, on by default.</li></ul><p>Shows the contents of whatever folder a native file open/save dialog was last navigated to, while SwiftList&#39;s own dialog-interception feature was active — a quick way back to wherever you were just browsing through a file picker, without needing to remember the path. The same hidden/system-file filtering and <a href="./index-drives.html#exclusion-rules">Exclusion Rules</a> the real index applies also apply here, so things like <code>$RECYCLE.BIN</code> don&#39;t show up. This tab doesn&#39;t appear at all if that hasn&#39;t happened yet this session, the folder no longer exists, or it&#39;s your Desktop (too often just the default landing spot, not a real navigation target).</p><h2 id="plugin-tabs" tabindex="-1">Plugin Tabs <a class="header-anchor" href="#plugin-tabs" aria-label="Permalink to &quot;Plugin Tabs&quot;">​</a></h2><p>Plugin-provided tabs (e.g. History, Favorites) each show a <strong>×</strong> button in the live panel to hide them for now. This is a panel-local &quot;hide it&quot; choice — separate from disabling the plugin component itself in <a href="./plugins.html">Plugins</a>, which stops it from being used at all. A tab closed this way is listed here, grouped by the plugin that provides it, unchecked; check it to bring it back.</p><p>Only tabs whose plugin component is currently enabled show up in this list — one disabled entirely under <a href="./plugins.html">Plugins</a> never becomes a tab candidate in the first place.</p><h2 id="tab-order" tabindex="-1">Tab Order <a class="header-anchor" href="#tab-order" aria-label="Permalink to &quot;Tab Order&quot;">​</a></h2><p>The same up/down-arrow reorder list used elsewhere in Settings (see <a href="./favorites.html">Favorites</a>), but covering the panel&#39;s tab strip as a whole — both built-in tabs (Recent Files, Last Directory) and every currently-visible plugin tab, all in one flat list, unlike Plugin Tabs above which groups by plugin. Move a tab up or down to change where it lands relative to the others; left to right in this list is left to right in the live panel.</p><p>Only tabs that would actually show right now are listed — a Recent Files/Last Directory tab you&#39;ve disabled above, or a plugin tab closed with its <strong>×</strong> button, has nothing to order until it&#39;s re-enabled or reopened.</p>',16)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
